public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Find a non-empty base string to generate substrings from
    String base = null;
    for (String s : strings) {
        if (s != null && !s.isEmpty()) {
            base = s;
            break;
        }
    }
    if (base == null) {
        return 0;
    }

    int baseLen = base.length();
    // Try lengths from longest to shortest
    for (int len = baseLen; len > 0; len--) {
        // Generate all unique substrings of current length
        java.util.Set<String> substrings = new java.util.HashSet<>();
        for (int i = 0; i + len <= baseLen; i++) {
            substrings.add(base.substring(i, i + len));
        }

        // Check each substring
        for (String sub : substrings) {
            String rev = new StringBuilder(sub).reverse().toString();
            boolean foundInAll = true;
            for (String s : strings) {
                if (s == null) {
                    foundInAll = false;
                    break;
                }
                if (!(s.contains(sub) || s.contains(rev))) {
                    foundInAll = false;
                    break;
                }
            }
            if (foundInAll) {
                return len; // maximal length found
            }
        }
    }

    return 0;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    if (cols == 0) {
        return 0;
    }

    boolean[][] visited = new boolean[rows][cols];
    int deposits = 0;

    // 8-directional moves
    int[] dx = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dy = {-1, 0, 1, -1, 1, -1, 0, 1};

    java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                deposits++;
                // Start DFS/BFS
                stack.push(new int[]{i, j});
                visited[i][j] = true;
                while (!stack.isEmpty()) {
                    int[] cell = stack.pop();
                    int x = cell[0], y = cell[1];
                    for (int dir = 0; dir < 8; dir++) {
                        int nx = x + dx[dir];
                        int ny = y + dy[dir];
                        if (nx >= 0 && nx < rows && ny >= 0 && ny < cols) {
                            if (grid[nx][ny] == '@' && !visited[nx][ny]) {
                                visited[nx][ny] = true;
                                stack.push(new int[]{nx, ny});
                            }
                        }
                    }
                }
            }
        }
    }
    return deposits;
}

