public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Basic validation of inputs
    if (n <= 0 || start == null || end == null || start.length == 0 || end.length == 0) {
        return "cannot be travelled";
    }

    int src = start[0];
    int dst = end[0];

    // Ensure the provided start and end indices are within bounds
    if (src < 0 || src >= n || dst < 0 || dst >= n) {
        return "cannot be travelled";
    }

    // Build adjacency list for the graph
    List<List<Integer>> adj = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        adj.add(new ArrayList<>());
    }

    if (paths != null) {
        for (int[] pair : paths) {
            if (pair == null || pair.length < 2) {
                continue; // Skip invalid path definitions
            }
            int a = pair[0];
            int b = pair[1];
            // Validate node indices
            if (a < 0 || a >= n || b < 0 || b >= n) {
                continue;
            }
            adj.get(a).add(b);
            adj.get(b).add(a); // undirected connection
        }
    }

    // Breadth‑first search to determine reachability
    boolean[] visited = new boolean[n];
    Deque<Integer> queue = new ArrayDeque<>();
    visited[src] = true;
    queue.offer(src);

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == dst) {
            return "can be travelled";
        }
        for (int neighbor : adj.get(current)) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.offer(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

