public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Basic validation of inputs
    try {
        if (n <= 0) return "cannot be travelled";
        if (start == null || end == null) return "cannot be travelled";
        if (start.length != n || end.length != n) return "cannot be travelled";
        if (paths == null) paths = new int[0][];
    } catch (Exception ignored) {
        return "cannot be travelled";
    }

    // Helper to produce a unique string key for a coordinate
    java.util.function.Function<int[], String> coordKey = arr -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < arr.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(arr[i]);
        }
        return sb.toString();
    };

    String startKey = coordKey.apply(start);
    String endKey = coordKey.apply(end);

    // If start and end are the same
    if (startKey.equals(endKey)) return "can be travelled";

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> adjacency = new java.util.HashMap<>();

    for (int[] path : paths) {
        if (path == null) continue;
        // Expecting a path to connect two coordinates
        // Two possible formats:
        // 1. length == 2*n  -> [coord1...coordn, coord2...coordn]
        // 2. length == 2    -> indices referencing coordinates (treat as string of indices)
        if (path.length == 2 * n) {
            int[] coordA = new int[n];
            int[] coordB = new int[n];
            System.arraycopy(path, 0, coordA, 0, n);
            System.arraycopy(path, n, coordB, 0, n);
            String keyA = coordKey.apply(coordA);
            String keyB = coordKey.apply(coordB);
            adjacency.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
            adjacency.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
        } else if (path.length == 2) {
            String keyA = Integer.toString(path[0]);
            String keyB = Integer.toString(path[1]);
            adjacency.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
            adjacency.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
        } else {
            // Unsupported path format; ignore or treat as invalid
            continue;
        }
    }

    // If either start or end node does not exist in graph, cannot travel
    if (!adjacency.containsKey(startKey) || !adjacency.containsKey(endKey)) {
        return "cannot be travelled";
    }

    // Breadth‑first search to determine reachability
    java.util.Deque<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        if (current.equals(endKey)) {
            return "can be travelled";
        }
        java.util.List<String> neighbours = adjacency.get(current);
        if (neighbours != null) {
            for (String neigh : neighbours) {
                if (!visited.contains(neigh)) {
                    visited.add(neigh);
                    queue.add(neigh);
                }
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || start.length != end.length) {
        return "cannot be travelled";
    }
    int dim = start.length;
    // If coordinates are single dimensional, use integer indices
    if (dim == 1) {
        int src = start[0];
        int dst = end[0];
        if (src == dst) {
            return "can be travelled";
        }
        if (paths == null || paths.length == 0) {
            return "cannot be travelled";
        }
        Map<Integer, List<Integer>> adj = new HashMap<>();
        for (int[] p : paths) {
            if (p.length != 2) continue;
            int u = p[0], v = p[1];
            adj.computeIfAbsent(u, k -> new ArrayList<>()).add(v);
            adj.computeIfAbsent(v, k -> new ArrayList<>()).add(u);
        }
        Set<Integer> visited = new HashSet<>();
        Deque<Integer> queue = new ArrayDeque<>();
        queue.add(src);
        visited.add(src);
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            List<Integer> neigh = adj.get(cur);
            if (neigh != null) {
                for (int nb : neigh) {
                    if (nb == dst) {
                        return "can be travelled";
                    }
                    if (!visited.contains(nb)) {
                        visited.add(nb);
                        queue.add(nb);
                    }
                }
            }
        }
        return "cannot be travelled";
    }
    // Multi-dimensional coordinate approach
    if (paths == null || paths.length == 0) {
        if (Arrays.equals(start, end)) {
            return "can be travelled";
        } else {
            return "cannot be travelled";
        }
    }
    String srcKey = Arrays.stream(start).mapToObj(String::valueOf).collect(Collectors.joining(","));
    String dstKey = Arrays.stream(end).mapToObj(String::valueOf).collect(Collectors.joining(","));
    if (srcKey.equals(dstKey)) {
        return "can be travelled";
    }
    Map<String, List<String>> adj = new HashMap<>();
    for (int[] p : paths) {
        if (p.length != 2 * dim) continue;
        int[] a = Arrays.copyOfRange(p, 0, dim);
        int[] b = Arrays.copyOfRange(p, dim, 2 * dim);
        String keyA = Arrays.stream(a).mapToObj(String::valueOf).collect(Collectors.joining(","));
        String keyB = Arrays.stream(b).mapToObj(String::valueOf).collect(Collectors.joining(","));
        adj.computeIfAbsent(keyA, k -> new ArrayList<>()).add(keyB);
        adj.computeIfAbsent(keyB, k -> new ArrayList<>()).add(keyA);
    }
    Set<String> visited = new HashSet<>();
    Deque<String> queue = new ArrayDeque<>();
    queue.add(srcKey);
    visited.add(srcKey);
    while (!queue.isEmpty()) {
        String cur = queue.poll();
        List<String> neigh = adj.get(cur);
        if (neigh != null) {
            for (String nb : neigh) {
                if (nb.equals(dstKey)) {
                    return "can be travelled";
                }
                if (!visited.contains(nb)) {
                    visited.add(nb);
                    queue.add(nb);
                }
            }
        }
    }
    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        return "Invalid input";
    }
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        return "Invalid date format";
    }
    try {
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);

        java.time.format.DateTimeFormatter monthFormatter = java.time.format.DateTimeFormatter.ofPattern("MMMM");
        String monthName = localDate.format(monthFormatter);

        java.time.DayOfWeek dow = localDate.getDayOfWeek();
        String dayName = dow.getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);

        return monthName + " " + day + ", " + year + " is a " + dayName;
    } catch (Exception e) {
        return "Invalid date format";
    }
}

