public boolean canArrange(int[] arr, int k) {
    // Validate input
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    if (k <= 0) {
        return false; // Division by zero or negative k is not allowed
    }

    int[] remainderCount = new int[k];

    // Count the frequency of each remainder modulo k
    for (int num : arr) {
        int remainder = ((num % k) + k) % k; // Handles negative numbers correctly
        remainderCount[remainder]++;
    }

    // Remainder 0 elements must pair among themselves
    if (remainderCount[0] % 2 != 0) {
        return false;
    }

    // Check pairs of complementary remainders
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) { // When k is even and r == k/2
            if (remainderCount[r] % 2 != 0) {
                return false;
            }
        } else {
            if (remainderCount[r] != remainderCount[complement]) {
                return false;
            }
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null) return false;
    int n = arr.length;
    if (n % 2 != 0) return false;
    if (k <= 0) return false; // k must be positive

    int[] freq = new int[k];
    for (int num : arr) {
        int rem = Math.floorMod(num, k); // ensures non-negative remainder
        freq[rem]++;
    }

    // Remainder 0 must have even count
    if (freq[0] % 2 != 0) return false;

    // If k is even, remainder k/2 must also have even count
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) return false;
    }

    // For all other remainders r, freq[r] should equal freq[k - r]
    for (int r = 1; r < k; r++) {
        int counterpart = k - r;
        if (r > counterpart) break; // avoid double checking
        if (r == counterpart) continue; // handled when k is even
        if (freq[r] != freq[counterpart]) return false;
    }

    return true;
}

