    for (int num : arr) {
        // Ensure remainder is non-negative
        int r = ((num % k) + k) % k;
        count[r]++;
    }

    // Check remainder 0 group
    if (count[0] % 2 != 0) {
        return false;
    }

    // If k is even, check group with remainder k/2
    if (k % 2 == 0) {
        if (count[k / 2] % 2 != 0) {
            return false;
        }
    }

    // Check other remainders
    int limit = k / 2;
    for (int r = 1; r <= limit; r++) {
        if (r == k - r) { // Handles the k/2 case already covered
            continue;
        }
        if (count[r] != count[k - r]) {
            return false;
        }
    }

    return true;
}

