    if (n % 2 != 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k; // handle negative numbers
        freq[rem]++;
    }
    // check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    // check remainders 1 to k/2
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // when k is even and r == k/2
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[r] != freq[k - r]) {
                return false;
            }
        }
    }
    return true;
}

