public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    // Count character occurrences using a TreeMap to keep keys sorted.
    java.util.TreeMap<Character, Integer> countMap = new java.util.TreeMap<>();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        countMap.merge(c, 1, Integer::sum);
    }

    StringBuilder result = new StringBuilder();
    while (!countMap.isEmpty()) {
        /* Ascending part */
        java.util.Map.Entry<Character, Integer> entry = countMap.firstEntry();
        char last = entry.getKey();
        result.append(last);
        if (entry.getValue() == 1) {
            countMap.remove(last);
        } else {
            countMap.put(last, entry.getValue() - 1);
        }

        while (true) {
            java.util.NavigableMap<Character, Integer> tail = countMap.tailMap(last, false);
            if (tail.isEmpty()) {
                break;
            }
            Character next = tail.firstKey();
            result.append(next);
            int val = tail.get(next);
            if (val == 1) {
                countMap.remove(next);
            } else {
                countMap.put(next, val - 1);
            }
            last = next;
        }

        if (countMap.isEmpty()) {
            break;
        }

        /* Descending part */
        entry = countMap.lastEntry();
        last = entry.getKey();
        result.append(last);
        if (entry.getValue() == 1) {
            countMap.remove(last);
        } else {
            countMap.put(last, entry.getValue() - 1);
        }

        while (true) {
            java.util.NavigableMap<Character, Integer> head = countMap.headMap(last, false);
            if (head.isEmpty()) {
                break;
            }
            Character next = head.lastKey();
            result.append(next);
            int val = head.get(next);
            if (val == 1) {
                countMap.remove(next);
            } else {
                countMap.put(next, val - 1);
            }
            last = next;
        }
    }
    return result.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    java.util.TreeMap<Integer, Integer> counts = new java.util.TreeMap<>();
    for (char ch : s.toCharArray()) {
        counts.merge((int) ch, 1, Integer::sum);
    }

    StringBuilder result = new StringBuilder();
    int remaining = s.length();

    java.util.function.BiConsumer<Integer, Void> consume = (key, ignore) -> {
        int n = counts.get(key);
        if (n == 1) {
            counts.remove(key);
        } else {
            counts.put(key, n - 1);
        }
    };

    while (remaining > 0) {
        // Ascending part
        if (counts.isEmpty()) {
            break;
        }
        int key = counts.firstKey();
        result.append((char) key);
        consume.accept(key, null);
        remaining--;
        int last = key;

        while (true) {
            Integer next = counts.higherKey(last);
            if (next == null) {
                break;
            }
            result.append((char) next);
            consume.accept(next, null);
            remaining--;
            last = next;
        }

        if (remaining == 0) {
            break;
        }

        // Descending part
        key = counts.lastKey();
        result.append((char) key);
        consume.accept(key, null);
        remaining--;
        last = key;

        while (true) {
            Integer next = counts.lowerKey(last);
            if (next == null) {
                break;
            }
            result.append((char) next);
            consume.accept(next, null);
            remaining--;
            last = next;
        }
    }

    return result.toString();
}

