public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    long totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) {
            continue;
        }
        long targetLong = (totalSum * k) / n;
        if (targetLong > Integer.MAX_VALUE || targetLong < Integer.MIN_VALUE) {
            continue;
        }
        int target = (int) targetLong;
        if (canPartition(nums, 0, k, target, new java.util.HashMap<String, Boolean>())) {
            return true;
        }
    }
    return false;
}

private boolean canPartition(int[] nums, int start, int k, int target, java.util.Map<String, Boolean> memo) {
    if (k == 0) {
        return target == 0;
    }
    if (start >= nums.length) {
        return false;
    }
    String key = start + "|" + k + "|" + target;
    if (memo.containsKey(key)) {
        return memo.get(key);
    }
    if (target < 0) {
        memo.put(key, false);
        return false;
    }
    // Try taking the current element
    if (canPartition(nums, start + 1, k - 1, target - nums[start], memo)) {
        memo.put(key, true);
        return true;
    }
    // Try skipping the current element
    boolean result = canPartition(nums, start + 1, k, target, memo);
    memo.put(key, result);
    return result;
}

public int minCostClimbingStairs(int[] cost) {
    // Validate input
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // Can start at step 1 with zero cost or step 0 with its cost, choose the cheaper
        return 0;
    }
    // Base cases for first two steps
    int prevPrev = cost[0]; // min cost to reach step 0
    int prev = cost[1];     // min cost to reach step 1
    if (n == 2) {
        return Math.min(prevPrev, prev);
    }
    // Iterate from step 2 to step n-1
    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(prev, prevPrev);
        prevPrev = prev;
        prev = current;
    }
    // The top can be reached from either the last step or the second-to-last step
    return Math.min(prev, prevPrev);
}

public int minCostClimbingStairs(int[] cost) {
    // Handle null or empty input
    if (cost == null || cost.length == 0) {
        return 0;
    }

    int n = cost.length;

    // For a single step, no cost is needed to reach the top
    if (n == 1) {
        return 0;
    }

    // dp[i] represents the minimum cost to reach step i
    // We only need the two previous values for DP
    int prevPrev = 0; // dp[i-2]
    int prev = 0;     // dp[i-1]

    // Iterate from step 2 (top is considered step n)
    for (int i = 2; i <= n; i++) {
        int costFromPrevOne = prev + cost[i - 1];
        int costFromPrevTwo = prevPrev + cost[i - 2];
        int curr = Math.min(costFromPrevOne, costFromPrevTwo);
        prevPrev = prev;
        prev = curr;
    }

    return prev;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return 0;
    }
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    int curr = 0; // dp[i]
    for (int i = 2; i <= n; i++) {
        int costFromPrev1 = prev1 + cost[i - 1];
        int costFromPrev2 = prev2 + cost[i - 2];
        curr = Math.min(costFromPrev1, costFromPrev2);
        prev2 = prev1;
        prev1 = curr;
    }
    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // You can start at step 1 (outside the staircase) and reach the top with no cost.
        return 0;
    }
    if (n == 2) {
        return Math.min(cost[0], cost[1]);
    }
    int prev2 = cost[0]; // dp[i-2]
    int prev1 = cost[1]; // dp[i-1]
    int current = 0;
    for (int i = 2; i < n; i++) {
        current = Math.min(prev2, prev1) + cost[i];
        prev2 = prev1;
        prev1 = current;
    }
    return Math.min(prev2, prev1);
}

