    }
    // For k large, 1 << k may overflow int. Use set with expected count.
    int total = 1 << k;
    // Quickly return false if total exceeds possible substrings
    if (n - k + 1 < total) {
        return false;
    }
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int code = 0;
    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (c != '0' && c != '1') {
            // Invalid character for binary string; consider this as failure.
            return false;
        }
        code = ((code << 1) & mask) | (c - '0');
        if (i >= k - 1) {
            seen[code] = true;
        }
    }
    for (boolean present : seen) {
        if (!present) {
            return false;
        }
    }
    return true;
}

