public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    if (n > Integer.MAX_VALUE / 2) {
        throw new IllegalArgumentException("n is too large to compute in int");
    }
    long result;
    if ((n & 1) == 0) { // even
        int half = n / 2;
        result = (long) half * half;
    } else { // odd
        int q = (n - 1) / 2;
        result = (long) q * (q + 1);
    }
    return (int) result;
}

public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    long m = ((long) n - 1) / 2;                     // floor((n-1)/2)
    long ops = (m + 1) * ((long) n - 1 - m);          // (m+1)*(n-1-m)
    return (int) ops;
}

public int minOperations(int n) {
    if (n <= 0) {
        return 0;
    }
    int half = n / 2;        // floor(n/2)
    int otherHalf = n - half; // ceil(n/2)
    return half * otherHalf;
}

