}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer.");
    }
    // Generate Fibonacci numbers up to k
    int[] fibs = new int[50]; // Enough to hold Fibonacci numbers <= Integer.MAX_VALUE
    fibs[0] = 1;
    fibs[1] = 1;
    int size = 2;
    while (true) {
        long next = (long) fibs[size - 1] + fibs[size - 2];
        if (next > k) {
            break;
        }
        fibs[size++] = (int) next;
    }

    int count = 0;
    int remaining = k;
    for (int i = size - 1; i >= 0 && remaining > 0; i--) {
        if (fibs[i] <= remaining) {
            remaining -= fibs[i];
            count++;
        }
    }
    return count;
}

