public String getSmallestString(int n, int k) {
    if (k < n || k > 26 * n) {
        return null; // impossible case
    }
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int remaining = k - n; // the extra value to distribute
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // 'z' is 26, so max extra per char is 25
        result[i] = (char) (result[i] + add);
        remaining -= add;
    }
    return new String(result);
}

