    StringBuilder sb = new StringBuilder();
    int len = digits.length();

    // Build the string in reverse order, inserting dots every three digits
    for (int i = 0; i < len; i++) {
        sb.append(digits.charAt(len - 1 - i));
        if ((i + 1) % 3 == 0 && i + 1 != len) {
            sb.append('.');
        }
    }

    // Reverse to correct order
    sb.reverse();

    // Add negative sign back if needed
    if (negative) {
        sb.insert(0, '-');
    }

    return sb.toString();
