private static int dfs(int lastIdx, int mask, Map<Long, Integer> memo, int[] A, boolean[] isSquare, int fullMask) {
    if (mask == fullMask) return 1;
    long key = (((long)mask) << 4) | lastIdx;
    if (memo.containsKey(key)) return memo.get(key);
    int count = 0;
    Set<Integer> used = new HashSet<>();
    for (int i = 0; i < A.length; i++) {
        if ((mask & (1 << i)) != 0) continue;
        if (!used.contains(A[i]) && isSquare[A[lastIdx] + A[i]]) {
            used.add(A[i]);
            count += dfs(i, mask | (1 << i), memo, A, isSquare, fullMask);
        }
    }
    memo.put(key, count);
    return count;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) return 0;
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    int maxArea = 0;
    int n = heights.length;
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int leftBoundary = stack.isEmpty() ? -1 : stack.peek();
            int width = i - leftBoundary - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

