    int m = mat.length, n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    int r = 0, c = 0;
    boolean up = true;
    while (index < result.length) {
        result[index++] = mat[r][c];
        if (up) {
            if (c == n - 1) {          // hit last column, go down
                r++;
                up = false;
            } else if (r == 0) {        // hit first row, go right
                c++;
                up = false;
            } else {                    // move up-left
                r--;
                c++;
            }
        } else { // down
            if (r == m - 1) {          // hit last row, go right
                c++;
                up = true;
            } else if (c == 0) {        // hit first column, go down
                r++;
                up = true;
            } else {                    // move down-right
                r++;
                c--;
            }
        }
    }
    return result;
}

