private static List<String> buildStrobogrammatic(int length) {
    if (length == 0) {
        return new ArrayList<String>() {{ add(""); }};
    }
    if (length == 1) {
        return new ArrayList<String>() {{ add("0"); add("1"); add("8"); }};
    }

    List<String> prev = buildStrobogrammatic(length - 2);
    List<String> result = new ArrayList<>();

    for (String inner : prev) {
        // Avoid leading zeros for numbers of outermost length
        result.add("1" + inner + "1");
        result.add("6" + inner + "9");
        result.add("8" + inner + "8");
        result.add("9" + inner + "6");
    }

    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    // Validate each point
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            return false;
        }
    }
    int[] p1 = points[0];
    int[] p2 = points[1];
    int[] p3 = points[2];

    // Check for duplicate points
    if ((p1[0] == p2[0] && p1[1] == p2[1]) ||
        (p1[0] == p3[0] && p1[1] == p3[1]) ||
        (p2[0] == p3[0] && p2[1] == p3[1])) {
        return false;
    }

    // Check for colinearity using the area of the triangle
    int area2 = (p1[0] - p2[0]) * (p1[1] - p3[1]) -
                (p1[0] - p3[0]) * (p1[1] - p2[1]);

    return area2 != 0;
}

