public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    int current = 1;
    for (int i = 0; i < n; i++) {
        result.add(current);
        long nextPrefix = (long) current * 10;
        if (nextPrefix <= n) {
            current = (int) nextPrefix;
        } else {
            // Move to the next number in lexicographical order
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    for (int i = 1; i <= 9 && i <= n; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int curr, int n, List<Integer> result) {
    if (curr > n) {
        return;
    }
    result.add(curr);
    for (int d = 0; d <= 9; d++) {
        long next = (long) curr * 10 + d;
        if (next > n) {
            break;
        }
        dfs((int) next, n, result);
    }
}

public static java.util.List<Integer> lexicalOrder(int n) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (n <= 0) {
        return result;
    }
    int curr = 1;
    while (result.size() < n) {
        result.add(curr);
        if ((long) curr * 10 <= n) {
            curr *= 10;
        } else if (curr % 10 != 9 && curr + 1 <= n) {
            curr += 1;
        } else {
            while (curr % 10 == 9) {
                curr /= 10;
            }
            curr += 1;
        }
    }
    return result;
}

