public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            min = Math.min(min, dp[i - square] + 1);
        }
        dp[i] = min;
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    // Handle non-positive input gracefully
    if (n <= 0) {
        return 0;
    }

    // dp[i] will hold the minimum number of perfect squares that sum to i
    int[] dp = new int[n + 1];
    dp[0] = 0; // base case: zero requires zero squares

    for (int i = 1; i <= n; i++) {
        int minCount = Integer.MAX_VALUE;
        // Only need to consider squares up to sqrt(i)
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < minCount) {
                minCount = candidate;
            }
        }
        dp[i] = minCount;
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int candidate = dp[i - j * j] + 1;
            if (candidate < min) {
                min = candidate;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0; // No squares needed for non-positive input
    }

    int sqrtN = (int) Math.sqrt(n);
    if (sqrtN * sqrtN == n) {
        return 1; // n itself is a perfect square
    }

    // Check if n can be expressed as a sum of two perfect squares
    for (int i = 1; i <= sqrtN; i++) {
        int rem = n - i * i;
        int sqrtRem = (int) Math.sqrt(rem);
        if (sqrtRem * sqrtRem == rem) {
            return 2;
        }
    }

    // Apply Legendre's three-square theorem
    int temp = n;
    while (temp % 4 == 0) {
        temp /= 4;
    }
    if (temp % 8 == 7) {
        return 4; // Numbers of the form 4^a(8b+7) require four squares
    }

    // If it didn't fall into the previous cases, it needs exactly three squares
    return 3;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    // Initialize with the worst case: using 1^2 repeated n times
    for (int i = 1; i <= n; i++) {
        dp[i] = i;
    }
    for (int i = 1; i <= n; i++) {
        int j = 1;
        int square = j * j;
        while (square <= i) {
            int candidate = dp[i - square] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
            j++;
            square = j * j;
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char ch = s.charAt(i);
        if (ch == ' ') {
            // reverse the collected word and append to result
            for (int j = word.length() - 1; j >= 0; j--) {
                result.append(word.charAt(j));
            }
            word.setLength(0); // reset word buffer
            result.append(ch); // preserve the space
        } else {
            word.append(ch);
        }
    }
    // append the last word (if any) after loop
    for (int j = word.length() - 1; j >= 0; j--) {
        result.append(word.charAt(j));
    }
    return result.toString();
}

